sys_variable_value.value:
(function execute(inputs, outputs) {
    var doppel = new DoppelIOCImport();
    var result = doppel.lookupIndicator(inputs.value, inputs.force_refresh);

    outputs.hit = !!result.hit;
    outputs.alert_id = result.alert_id || '';
    outputs.brand = result.brand || '';
    outputs.product_type = result.product_type || '';
    outputs.queue_state = result.queue_state || '';
    outputs.entity_state = result.entity_state || '';
    outputs.doppel_link = result.doppel_link || '';
    outputs.error = result.error || '';
    outputs.source = result.checkedDoppel === false ? 'local' : 'doppel';
})(inputs, outputs);

